-- ============================================================
-- 安心伴（anxinban）真实感模拟数据插入脚本 v2
-- ============================================================
-- 用途：为 elder_001 生成最近30天（2026-06-16 ~ 2026-07-16）的
--       真实感体征数据（体温、心率、血压、血氧）及最新告警数据
-- 适用数据库：anxinban (MySQL 8.0)
-- 生成时间：2026-07-16
-- 数据特点：
--   - 体温：一天多个时间点，早晚低(36.2-36.5)、午后高(36.5-37.1)，模拟正常生理波动
--   - 心率：静息(62-75)、活动后(78-95)，早晚偏低、白天偏高
--   - 血压：收缩压115-145，舒张压75-92，早晚略高
--   - 血氧：94%-99%，基本稳定
--   - 告警：包含7月的近期告警数据
-- ============================================================

USE anxinban;

-- ============================================================
-- 先清理旧的模拟数据，避免主键冲突
-- ============================================================
DELETE FROM `body_temperature` WHERE `bt_id` LIKE 'bt_sim_%' OR `bt_id` LIKE 'bt_v2_%';
DELETE FROM `heart_rate` WHERE `hr_id` LIKE 'hr_sim_%' OR `hr_id` LIKE 'hr_v2_%';
DELETE FROM `blood_pressure` WHERE `bp_id` LIKE 'bp_sim_%' OR `bp_id` LIKE 'bp_v2_%';
DELETE FROM `blood_oxygen` WHERE `bo_id` LIKE 'bo_sim_%' OR `bo_id` LIKE 'bo_v2_%';

